      "outputType": "markdown",
      "output": "function createDrumMachine(ctx,destination){\nconst voices=[\"kick\",\"snare\",\"clap\",\"chh\",\"ohh\",\"tom\",\"rim\",\"crash\"],outs={},sr=ctx.sampleRate,n=sr*2|0,buf=ctx.createBuffer(1,n,sr),d=buf.getChannelData(0);\nfor(let i=0;i<n;i++)d[i]=Math.random()*2-1;\nvoices.forEach(v=>{const g=ctx.createGain();g.connect(destination);outs[v]=g});\nlet open=null;\nconst cn=(...a)=>{for(let i=0;i<a.length-1;i++)a[i].connect(a[i+1]);return a[a.length-1]};\nconst gn=x=>{const g=ctx.createGain();g.gain.value=x;return g};\nconst env=(t,a,dur,p)=>{const g=ctx.createGain(),q=g.gain;q.setValueAtTime(0,t);q.linearRampToValueAtTime(p,t+a);q.exponentialRampToValueAtTime(1e-4,t+dur);return g};\nconst osc=(ty,f,t,dur)=>{const o=ctx.createOscillator();o.type=ty;o.frequency.setValueAtTime(f,t);o.start(t);o.stop(t+dur+.05);return o};\nconst noise=(t,dur)=>{const s=ctx.createBufferSource();s.buffer=buf;s.start(t,Math.random()*Math.max(0,buf.duration-dur-.05));s.stop(t+dur+.05);return s};\nconst flt=(ty,f,Q)=>{const b=ctx.createBiquadFilter();b.type=ty;b.frequency.value=f;if(Q)b.Q.value=Q;return b};\nconst metal=(t,dur,f0)=>{const m=gn(.18);[2,3,4.16,5.43,6.79,8.21].forEach(r=>osc(\"square\",f0*r,t,dur).connect(m));return m};\nconst hat=(t,v,dur,o)=>{const g=env(t,.001,dur,v),hp=flt(\"highpass\",7000);cn(metal(t,dur,40),flt(\"bandpass\",10000,.8),hp);cn(noise(t,dur),gn(.6),hp);cn(hp,g,o);return g};\nconst choke=t=>{if(open&&t>open.t&&t<open.e){const q=open.g.gain;if(q.cancelAndHoldAtTime)q.cancelAndHoldAtTime(t);else q.cancelScheduledValues(t);q.setTargetAtTime(0,t,.008)}if(open&&t>open.t)open=null};\nfunction trigger(voice,time,velocity){\nconst o=outs[voice];if(!o)return;\nconst t=Math.max(time==null?0:time,ctx.currentTime),v=[.4,.7,1][Math.min(3,Math.max(1,Math.round(velocity)||2))-1];\nswitch(voice){\ncase\"kick\":{const k=osc(\"sine\",150,t,.6);k.frequency.exponentialRampToValueAtTime(45,t+.18);cn(k,env(t,.003,.55,v),o);cn(noise(t,.02),flt(\"highpass\",1500),env(t,.001,.018,v*.6),o);break}\ncase\"snare\":{const s=osc(\"triangle\",180,t,.2);s.frequency.exponentialRampToValueAtTime(150,t+.12);cn(s,env(t,.001,.16,v*.55),o);cn(noise(t,.25),flt(\"bandpass\",2500,.8),env(t,.001,.22,v*.9),o);break}\ncase\"clap\":{const g=ctx.createGain(),q=g.gain;q.setValueAtTime(0,t);for(let k=0;k<3;k++){const s=t+k*.011;q.setValueAtTime(v,s);q.exponentialRampToValueAtTime(v*.08,s+.01)}q.setValueAtTime(v*.75,t+.033);q.exponentialRampToValueAtTime(1e-4,t+.3);cn(noise(t,.32),flt(\"bandpass\",1300,1.4),gn(1.6),g,o);break}\ncase\"chh\":choke(t);hat(t,v*.8,.06,o);break;\ncase\"ohh\":{choke(t);const g=hat(t,v*.7,.5,o);open={g,t,e:t+.5};break}\ncase\"tom\":{const s=osc(\"sine\",140,t,.5);s.frequency.exponentialRampToValueAtTime(90,t+.3);cn(s,env(t,.002,.45,v),o);break}\ncase\"rim\":cn(osc(\"square\",1700,t,.05),flt(\"highpass\",900),env(t,.0005,.035,v*.5),o);cn(osc(\"triangle\",480,t,.05),env(t,.0005,.03,v*.5),o);break;\ncase\"crash\":cn(noise(t,1.8),flt(\"highpass\",4500),env(t,.002,1.8,v*.6),o);cn(metal(t,1.8,55),flt(\"highpass\",6000),env(t,.002,1.4,v*.35),o);break}\n}\nreturn{voices,trigger,output:v=>outs[v]}\n}"
