      "outputType": "markdown",
      "output": "```js\nfunction createSynths(ctx){\nconst mtof=n=>440*Math.pow(2,(n-69)/12),now=()=>ctx.currentTime,cl=(v,a,b)=>Math.max(a,Math.min(b,v));\nconst G=v=>{const g=ctx.createGain();g.gain.value=v;return g};\nconst F=(type,f,q)=>{const b=ctx.createBiquadFilter();b.type=type;b.frequency.value=f;b.Q.value=q||0.7;return b};\nconst rms=a=>{const b=new Float32Array(a.fftSize);a.getFloatTimeDomainData(b);let s=0;for(let i=0;i<b.length;i++)s+=b[i]*b[i];return cl(Math.sqrt(s/b.length),0,1)};\nconst mIn=G(1),comp=ctx.createDynamicsCompressor();comp.threshold.value=-14;comp.ratio.value=4;comp.knee.value=8;comp.attack.value=0.005;comp.release.value=0.2;\nconst djf=F('lowpass',20000,0.9),mG=G(0.8),an=ctx.createAnalyser();an.fftSize=2048;an.smoothingTimeConstant=0.8;\nmIn.connect(comp);comp.connect(djf);djf.connect(mG);mG.connect(an);an.connect(ctx.destination);\nconst fxIn=G(1),fxRet=G(1),conv=ctx.createConvolver(),sr=ctx.sampleRate,L=Math.floor(sr*2.5),ir=ctx.createBuffer(2,L,sr);\nfor(let c=0;c<2;c++){const d=ir.getChannelData(c);for(let i=0;i<L;i++)d[i]=(Math.random()*2-1)*Math.pow(1-i/L,3)}\nconv.buffer=ir;\nconst dl=ctx.createDelay(2),fb=G(0.38),dlf=F('lowpass',3500),dw=G(0.5);dl.delayTime.value=0.375;\nfxIn.connect(conv);conv.connect(fxRet);fxIn.connect(dl);dl.connect(dlf);dlf.connect(fb);fb.connect(dl);dlf.connect(dw);dw.connect(fxRet);\nconst chans={};\nconst mk=(name,inp)=>{const input=inp||G(1),vol=G(0.8),pan=ctx.createStereoPanner(),send=G(0),a=ctx.createAnalyser();a.fftSize=1024;\ninput.connect(vol);vol.connect(pan);pan.connect(a);a.connect(mIn);if(name!=='fx'){pan.connect(send);send.connect(fxIn)}\nreturn{input,setVolume:v=>vol.gain.setTargetAtTime(cl(v,0,1.5),now(),0.02),setPan:p=>pan.pan.setTargetAtTime(cl(p,-1,1),now(),0.02),setSend:s=>send.gain.setTargetAtTime(cl(s,0,1),now(),0.02),level:()=>rms(a)}};\n['drums','bass','keys'].forEach(n=>chans[n]=mk(n));chans.fx=mk('fx',fxRet);\nconst mixer={channel:n=>chans[n]||(chans[n]=mk(n)),analyser:an,\nsetCutoff:hz=>djf.frequency.setTargetAtTime(cl(hz,20,20000),now(),0.02),\nsetMaster:v=>mG.gain.setTargetAtTime(cl(v,0,1.5),now(),0.02),masterLevel:()=>rms(an)};\nconst bo=ctx.createOscillator();bo.type='sawtooth';const bf=F('lowpass',500,12),bv=G(0);\nbo.connect(bf);bf.connect(bv);bv.connect(chans.bass.input);bo.start();\nconst bp={cutoff:500,resonance:12};let slid=false,lastEnd=0;\nconst bass={\nplay(note,time,len,accent,slide,sps){sps=sps||0.125;len=len||1;\nconst t=Math.max(time||0,now()),f=mtof(note),fr=bo.frequency,g=bv.gain,c=bf.frequency,glide=slid&&t<=lastEnd+0.03;\nconst amp=accent?0.55:0.33,base=bp.cutoff,pk=cl(base*(accent?6:3.5)+(accent?900:300),40,18000);\ng.cancelScheduledValues(t);fr.cancelScheduledValues(t);\nif(glide){fr.setTargetAtTime(f,t,sps*0.3);g.setTargetAtTime(amp,t,0.01)}\nelse{fr.setValueAtTime(f,t);g.setValueAtTime(0,t);g.setTargetAtTime(amp,t,0.003)}\nif(!glide||accent){c.cancelScheduledValues(t);c.setTargetAtTime(pk,t,0.003);c.setTargetAtTime(base,t+0.01,accent?0.09:0.16)}\nbf.Q.setValueAtTime(cl(bp.resonance*(accent?1.3:1),0.1,30),t);\nconst end=t+len*sps;\nif(slide)g.setTargetAtTime(0,end+sps*0.5,0.015);else g.setTargetAtTime(0,t+len*sps*0.9,0.012);\nslid=!!slide;lastEnd=end},\nset(o){o=o||{};if(o.cutoff!=null){bp.cutoff=cl(o.cutoff,40,18000);bf.frequency.setTargetAtTime(bp.cutoff,now(),0.02)}\nif(o.resonance!=null){bp.resonance=cl(o.resonance,0.1,30);bf.Q.setTargetAtTime(bp.resonance,now(),0.02)}\nif(o.wave==='square'||o.wave==='sawtooth')bo.type=o.wave}};\nconst kIn=G(1),cd=ctx.createDelay(0.1),cw=G(0.5),lfo=ctx.createOscillator(),lg=G(0.004);cd.delayTime.value=0.02;lfo.frequency.value=0.5;\nkIn.connect(chans.keys.input);kIn.connect(cd);cd.connect(cw);cw.connect(chans.keys.input);lfo.connect(lg);lg.connect(cd.delayTime);lfo.start();\nconst keys={chord(notes,time,sec,vel){if(!notes||!notes.length)return;vel=vel==null?0.8:vel;sec=Math.max(0.05,sec||1);\nconst t=Math.max(time||0,now()),f=F('lowpass',600,0.6),e=G(0),a=Math.min(0.35,sec*0.4),h=t+Math.max(a,sec),r=0.6,lv=vel*0.35/notes.length;\nf.frequency.setValueAtTime(600,t);f.frequency.linearRampToValueAtTime(2200,t+Math.min(0.8,sec*0.5));\nf.connect(e);e.connect(kIn);\ne.gain.setValueAtTime(0,t);e.gain.linearRampToValueAtTime(lv,t+a);e.gain.setValueAtTime(lv,h);e.gain.setTargetAtTime(0,h,r/3);\nconst stop=h+r*2.5;\nnotes.forEach(n=>[-8,8].forEach(d=>{const o=ctx.createOscillator();o.type='sawtooth';o.frequency.value=mtof(n);o.detune.value=d;o.connect(f);o.start(t);o.stop(stop)}));\nsetTimeout(()=>{try{e.disconnect()}catch(x){}},(stop-now()+0.2)*1000)}};\nconst setTempo=bpm=>dl.delayTime.setTargetAtTime(Math.min(2,0.75*60/cl(bpm||120,30,300)),now(),0.05);\nsetTempo(120);\nreturn{bass,keys,mixer,setTempo}}\n```\n\nNot verified: I have not run this code in a browser. I have not listened to the output, measured the levels or checked the analyser readings."
