      "outputType": "markdown",
      "output": "```js\nfunction createSequencer(ctx,onStep){\nlet bpm=120,sw=0,pat='A',chain=null,ci=0,st=0,nt=0,tm=null,q=[],last=null;\nconst len=()=>60/bpm/4,cur=()=>chain?chain[ci%chain.length]:pat;\nfunction tick(){\nconst end=ctx.currentTime+0.12;\nwhile(nt<end){\nconst p=cur(),t=nt+(st%2?sw*len():0);\ntry{onStep(p,st,t)}catch(e){console.error(e)}\nq.push({patternName:p,step:st,time:t});\nif(q.length>256)q.shift();\nnt+=len();\nif(++st>15){st=0;if(chain)ci=(ci+1)%chain.length}\n}\n}\nreturn{\nstart(){\nif(tm)return;\nif(ctx.state==='suspended'&&ctx.resume)ctx.resume().catch(()=>{});\nst=0;ci=0;q=[];last=null;\nnt=ctx.currentTime+0.05;\ntick();\ntm=setInterval(tick,25);\n},\nstop(){\nif(tm)clearInterval(tm);\ntm=null;q=[];last=null;\n},\nplaying(){return!!tm},\nsetTempo(b){b=+b;if(isFinite(b))bpm=Math.min(300,Math.max(20,b))},\nsetSwing(a){a=+a;if(isFinite(a))sw=Math.min(0.5,Math.max(0,a))},\nsetPattern(n){if(n!=null)pat=String(n)},\nsetChain(l){\nchain=Array.isArray(l)&&l.length?l.map(String):null;\nif(chain)ci%=chain.length;else ci=0;\n},\nposition(){\nreturn last?{patternName:last.patternName,step:last.step,time:last.time,chainIndex:ci}:{patternName:cur(),step:tm?st:0,time:null,chainIndex:ci};\n},\ndrain(now){\nlet r=null;\nwhile(q.length&&q[0].time<=now)r=q.shift();\nif(r)last=r;\nreturn r;\n}\n};\n}\n```"
